CREATE TABLE public.vehicle_private_identifiers(vehicle_id uuid PRIMARY KEY REFERENCES public.vehicles(id),workspace_id uuid NOT NULL,vin text NOT NULL CHECK(vin ~ '^[A-HJ-NPR-Z0-9]{17}$'));
GRANT SELECT,INSERT,UPDATE ON public.vehicle_private_identifiers TO authenticated;GRANT ALL ON public.vehicle_private_identifiers TO service_role;
ALTER TABLE public.vehicle_private_identifiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_vehicle_manager ON public.vehicle_private_identifiers TO authenticated USING(public.business_record_access(workspace_id,'vehicles',vehicle_id,'manage')) WITH CHECK(public.business_record_access(workspace_id,'vehicles',vehicle_id,'manage') AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=vehicle_id AND v.workspace_id=vehicle_private_identifiers.workspace_id));
COMMENT ON COLUMN public.vehicles.vin IS 'DEPRECATED: full VIN stored only in manager-scoped vehicle_private_identifiers; never populate this broadly readable field.';
CREATE FUNCTION public.vehicle_vin_private_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.vin IS NOT NULL AND NEW.vin<>'' THEN RAISE EXCEPTION 'Full VIN must use private authorized storage';END IF;RETURN NEW;END $$;
CREATE TRIGGER vehicle_vin_private_guard BEFORE INSERT OR UPDATE OF vin ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.vehicle_vin_private_guard();
CREATE FUNCTION public.vehicle_masked_vin(_vehicle uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid;v text;BEGIN SELECT workspace_id INTO ws FROM public.vehicles WHERE id=_vehicle;IF NOT public.business_record_access(ws,'vehicles',_vehicle,'read') THEN RETURN NULL;END IF;SELECT vin INTO v FROM public.vehicle_private_identifiers WHERE vehicle_id=_vehicle;RETURN CASE WHEN v IS NULL THEN NULL ELSE '•••••••••••••'||right(v,4) END;END $$;
REVOKE ALL ON FUNCTION public.vehicle_masked_vin(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.vehicle_masked_vin(uuid) TO authenticated;